      sleep 3
    done

    if [ -z "$UPF_IP" ]; then
      echo "[wrapper] WARNING: UPF IP not resolved, using placeholder"
      UPF_IP="UPF_SERVICE_NAME"
    fi

    echo "[wrapper] UPF Pod IP: $UPF_IP"
    sed -i "s/UPF_SERVICE_NAME/$UPF_IP/g" /tmp/smfcfg.yaml
{{- else }}
    echo "[wrapper] Resolving ULCL UPF Pod IPs from Headless Services..."
