      PSAUPF1_IP=$(getent hosts {{ $.Release.Name }}-free5gc-upf-psaupf1-service 2>/dev/null | awk '{print $1}' | head -1)
      PSAUPF2_IP=$(getent hosts {{ $.Release.Name }}-free5gc-upf-psaupf2-service 2>/dev/null | awk '{print $1}' | head -1)

