cat >> ~/work/deploy/free5gc-values.yaml <<'EOF'

# Single-node 4-vCPU cluster: lower the UPF CPU *requests* (limits unchanged) so rolling updates can schedule.
free5gc-upf:
  iupf1:
    resources:
      requests: {cpu: 100m, memory: 256Mi}
      limits: {cpu: 1000m, memory: 1024Mi}
  psaupf1:
    resources:
      requests: {cpu: 100m, memory: 256Mi}
      limits: {cpu: 1000m, memory: 1024Mi}
  psaupf2:
    resources:
      requests: {cpu: 100m, memory: 256Mi}
      limits: {cpu: 1000m, memory: 1024Mi}
EOF
cd ~/work/src/free5gc-helm/charts; helm upgrade free5gc-helm ./free5gc -n free5gc -f ~/work/deploy/free5gc-values.yaml --timeout 5m 2>&1 | head -3; sleep 60; kubectl -n free5gc get pods | grep -E "upf|smf"

